/**
 * Independently exercise fixed packaged-resource hashes and exact custom-origin request boundaries.
 * Symbol index (generated by tools/update-symbol-index.ts):
 * @@SYMBOL_INDEX_START
 * - variable native: line 15
 * - variable roots: line 26
 * - function fixture: line 27
 * @@SYMBOL_INDEX_END
 */
import fs from "node:fs";
import path from "node:path";
import { createHash } from "node:crypto";
import { createRequire } from "node:module";
import { afterEach, describe, expect, it } from "vitest";
const native = createRequire(import.meta.url)("../../desktop/protocol.cjs") as {
  responseFor(
    request: { url: string; method: string },
    assets: Map<string, { bytes: Buffer; type: string }>,
  ): Response;
  verifiedResources(
    root: string,
    owner: string,
  ): { assets: Map<string, { bytes: Buffer; type: string }>; metadata: { source: string } };
  isOwnURL(value: string): boolean;
};
const roots: string[] = [];
function fixture() {
  fs.mkdirSync(".runtime", { recursive: true });
  const root = fs.mkdtempSync(path.resolve(".runtime/portal-resources-"));
  roots.push(root);
  const owner = path.join(root, "owner");
  fs.mkdirSync(owner);
  const files: Record<string, string> = {},
    core: Record<string, string> = {},
    owned: Record<string, string> = {};
  for (const [base, names, inventory] of [
    [root, ["web/index.html", "web/workbench/index.html", "web/docs/test/2.0/index.html"], files],
    [
      root,
      [
        "core/lib/workspace.js",
        "core/lib/search.js",
        "core/lib/comparison.js",
        "core/starter.json",
        "core/NOTICES.txt",
      ],
      core,
    ],
    [owner, ["files.cjs", "main.mjs", "preload.cjs", "protocol.cjs", "state.cjs"], owned],
  ] as const)
    for (const name of names) {
      const bytes = Buffer.from(
        name.endsWith("html") ? "<h1>Actual resource bytes</h1>" : "resource",
      );
      fs.mkdirSync(path.dirname(path.join(base, name)), { recursive: true });
      fs.writeFileSync(path.join(base, name), bytes);
      inventory[name] = createHash("sha256").update(bytes).digest("hex");
    }
  const metadata = {
    schema: 1,
    product: "versioned-product-knowledge-portal",
    version: "0.2.0",
    source: "a".repeat(40),
    sourceDirty: false,
    files,
    core,
    owner: owned,
  };
  fs.writeFileSync(path.join(root, "SOURCE.json"), JSON.stringify(metadata));
  return { root, owner, metadata };
}
afterEach(() => {
  for (const root of roots.splice(0)) {
    if (!root.startsWith(path.resolve(".runtime") + path.sep))
      throw new Error("Not an owned fixture.");
    fs.rmSync(root, { recursive: true, force: true });
  }
});
describe("verified native scheme", () => {
  it("loads exact hashed bytes including version-qualified directories and serves GET/HEAD only", async () => {
    const { root, owner } = fixture(),
      value = native.verifiedResources(root, owner);
    expect(value.metadata.source).toBe("a".repeat(40));
    const response = native.responseFor(
      { url: "portal://workbench/workbench/", method: "GET" },
      value.assets,
    );
    expect(response.status).toBe(200);
    expect(await response.text()).toBe("<h1>Actual resource bytes</h1>");
    expect(response.headers.get("content-security-policy")).toContain("object-src 'none'");
    expect(response.headers.get("content-security-policy")).not.toContain("unsafe-inline");
    expect(
      await native
        .responseFor({ url: "portal://workbench/docs/test/2.0/", method: "HEAD" }, value.assets)
        .text(),
    ).toBe("");
    expect(value.assets.has("/core/starter.json")).toBe(false);
  });
  it.each([
    "https://workbench/workbench/",
    "portal://foreign/workbench/",
    "portal://user:password@workbench/workbench/",
    "portal://workbench:80/workbench/",
    "portal://workbench/workbench/?file=secret",
    "portal://workbench/core/starter.json",
    "portal://workbench/unknown",
    "portal://workbench/../owner.json",
  ])("refuses foreign/private/ambiguous request %s", (url) => {
    const { root, owner } = fixture();
    expect(
      native.responseFor({ url, method: "GET" }, native.verifiedResources(root, owner).assets)
        .status,
    ).toBe(404);
  });
  it("refuses unsupported methods and malformed addresses", () => {
    const { root, owner } = fixture(),
      assets = native.verifiedResources(root, owner).assets;
    expect(native.responseFor({ url: "portal://workbench/", method: "POST" }, assets).status).toBe(
      404,
    );
    expect(native.responseFor({ url: "not a URL", method: "GET" }, assets).status).toBe(400);
    expect(native.isOwnURL("not a URL")).toBe(false);
    expect(native.isOwnURL("portal://workbench/workbench/")).toBe(true);
    expect(native.isOwnURL("portal://workbench.evil/workbench/")).toBe(false);
  });
  it("refuses tampered actual owner and public bytes before loading a core", () => {
    const { root, owner } = fixture();
    fs.appendFileSync(path.join(owner, "main.mjs"), "changed");
    expect(() => native.verifiedResources(root, owner)).toThrow(/bytes changed/u);
    const second = fixture();
    fs.writeFileSync(path.join(second.root, "web/index.html"), "different");
    expect(() => native.verifiedResources(second.root, second.owner)).toThrow(/bytes changed/u);
  });
  it("refuses extra owner modules and path-traversal inventory entries", () => {
    const { root, owner, metadata } = fixture();
    metadata.owner["unexpected.cjs"] = "a".repeat(64);
    fs.writeFileSync(path.join(root, "SOURCE.json"), JSON.stringify(metadata));
    expect(() => native.verifiedResources(root, owner)).toThrow(/identity/u);
    delete metadata.owner["unexpected.cjs"];
    metadata.files["web/../private.txt"] = "a".repeat(64);
    fs.writeFileSync(path.join(root, "SOURCE.json"), JSON.stringify(metadata));
    expect(() => native.verifiedResources(root, owner)).toThrow(/path or hash/u);
  });
});
